// ─── Config: resolve a unidade e o pixel ────────────────────────────────────
//
// O multi-tenant sai do phone_number_id: cada unidade tem o seu número de
// WhatsApp, e ele vem em toda mensagem. Assim o mesmo fluxo serve a rede inteira
// sem variável por unidade — acrescentar clínica é acrescentar uma linha no mapa.
//
// META_CAPI_UNIDADES é um JSON no ambiente do n8n, por exemplo:
// {"728123456789012":{"unidade":"imperatriz","pixel":"1076495867156119"}}
//
// Se o mapa não tiver o número, o evento NÃO é enviado. Mandar para o pixel
// errado suja o aprendizado da campanha de outra clínica, e isso não tem desfazer.

const mapa = (() => {
  try { return JSON.parse($env.META_CAPI_UNIDADES || '{}'); }
  catch { return {}; }
})();

const cfg = {
  mapa,
  token: $env.META_CAPI_TOKEN || '',
  graphVersion: $env.META_GRAPH_VERSION || 'v23.0',
  // Pixel único de fallback, para quem roda uma clínica só.
  pixelPadrao: $env.META_PIXEL_ID || '',
  // Código de teste do Gerenciador de Eventos. Com ele preenchido, o evento
  // aparece em "Eventos de teste" e NÃO entra na otimização — é o que permite
  // conferir antes de valer para a campanha.
  testEventCode: $env.META_CAPI_TEST_CODE || '',
  // Janela de atribuição do clique no WhatsApp. Evento mais velho que isso a
  // Meta aceita mas não credita ao anúncio; enviar só gera ruído.
  janelaDias: Number($env.META_CAPI_JANELA_DIAS || 7),
};

// Cada etapa da Kommo vira um evento do funil da Meta.
const EVENTOS = {
  mensagem:           'ViewContent',
  lead_quente:        'Lead',
  agendamento:        'AddToCart',
  consulta_realizada: 'InitiateCheckout',
  compra:             'Purchase',
};

return [{ json: { cfg, EVENTOS } }];

// Monta o ViewContent a partir dos cliques que o rastreio já gravou.
// Lê de ctwa_eventos em vez de tocar no fluxo que roda — o rastreio continua
// intocado e este aqui só observa o que ele produziu.
const { cfg, EVENTOS } = $('Config').first().json;
const agora = Math.floor(Date.now() / 1000);
const saida = [];

for (const item of $input.all()) {
  const e = item.json;
  const destino = cfg.mapa[String(e.phone_number_id)] || null;
  const pixel = destino?.pixel || cfg.pixelPadrao;

  if (!pixel) { continue; }              // sem pixel não há para onde mandar
  if (!e.ctwa_clid) { continue; }        // sem clique não há o que atribuir

  const quando = Math.floor(new Date(e.primeiro_contato_em).getTime() / 1000);
  if (agora - quando > cfg.janelaDias * 86400) { continue; }  // fora da janela

  saida.push({ json: {
    pixel,
    unidade: destino?.unidade || 'desconhecida',
    event_id: `vc-${e.wamid}`,
    event_name: EVENTOS.mensagem,
    event_time: quando,
    ctwa_clid: e.ctwa_clid,
    telefone: e.telefone_digits,
    wamid: e.wamid,
    kommo_lead_id: null,
    corpo: {
      data: [{
        event_name: EVENTOS.mensagem,
        event_time: quando,
        event_id: `vc-${e.wamid}`,
        action_source: 'business_messaging',
        messaging_channel: 'whatsapp',
        user_data: { ctwa_clid: e.ctwa_clid },
      }],
      ...(cfg.testEventCode ? { test_event_code: cfg.testEventCode } : {}),
    },
  }});
}
return saida;

// O webhook da Kommo chega em notação de colchetes; este nó normaliza
// e devolve { evento, kommo_lead_id, ctwa_clid, phone_number_id, valor }.
// Preencher conforme o mapa de etapas da unidade.
return $input.all();

// Traduz a mudança de etapa na Kommo num evento do funil da Meta.
//
// A regra dura: sem ctwa_clid no cartão, NÃO envia. O lead que não veio de
// anúncio virando Purchase no pixel ensina a Meta a otimizar para a audiência
// errada — é pior que não enviar nada.
const { cfg, EVENTOS } = $('Config').first().json;
const agora = Math.floor(Date.now() / 1000);
const saida = [];

for (const item of $input.all()) {
  const d = item.json;
  if (!d.ctwa_clid) continue;
  const pixel = (cfg.mapa[String(d.phone_number_id)] || {}).pixel || cfg.pixelPadrao;
  if (!pixel || !d.evento) continue;

  const nome = EVENTOS[d.evento];
  if (!nome) continue;   // etapa sem evento correspondente: não inventa

  const corpo = {
    data: [{
      event_name: nome,
      event_time: agora,
      event_id: `${d.evento}-${d.kommo_lead_id}`,
      action_source: 'business_messaging',
      messaging_channel: 'whatsapp',
      user_data: { ctwa_clid: d.ctwa_clid },
      ...(d.valor ? { custom_data: { currency: 'BRL', value: Number(d.valor) } } : {}),
    }],
    ...(cfg.testEventCode ? { test_event_code: cfg.testEventCode } : {}),
  };

  saida.push({ json: {
    pixel, unidade: d.unidade || 'desconhecida',
    event_id: `${d.evento}-${d.kommo_lead_id}`,
    event_name: nome, event_time: agora,
    ctwa_clid: d.ctwa_clid, telefone: d.telefone || null,
    wamid: null, kommo_lead_id: String(d.kommo_lead_id), corpo,
  }});
}
return saida;

